/** Exercise normal planner choice through SPARQL, with all competing execution strategies left available. */
@ResourceLock(Resources.SYSTEM_PROPERTIES)
class SparseJoinAggregateAutomaticTest {

	private static final String SPARSE_PROPERTY = "rdf4j.lmdb.sparseJoinAggregate.enabled";
	private static final String NATIVE_PROPERTY = "rdf4j.lmdb.nativeQueryEngine.enabled";
	private static final String SPARSE_PATH = "sparseJoinAggregate";
	private static final String EX = "urn:sparse-automatic:";
	private static final int ENDPOINTS = 32;
	private static final int JOIN_KEYS = 64;
	private static final String QUERY = """
			SELECT ?a ?b (COUNT(?j) AS ?count) WHERE {
			  ?a <urn:sparse-automatic:p> ?j . ?j <urn:sparse-automatic:q> ?b
			} GROUP BY ?a ?b
			""";

	private final Map<String, String> previousProperties = new HashMap<>();

	@BeforeEach
	void useNormalNativeDefaults() {
		for (String property : List.of(SPARSE_PROPERTY, NATIVE_PROPERTY)) {
			previousProperties.put(property, System.getProperty(property));
			System.clearProperty(property);
		}
	}

	@AfterEach
	void restoreProperties() {
		for (Map.Entry<String, String> entry : previousProperties.entrySet()) {
			if (entry.getValue() == null) {
				System.clearProperty(entry.getKey());
			} else {
				System.setProperty(entry.getKey(), entry.getValue());
			}
		}
	}

	@Test
	void choosesSparseAutomaticallyForBranchingJoinWithoutOptIn(@TempDir Path directory) {
		assertNull(System.getProperty(SPARSE_PROPERTY));
		Observation actual = executeFixture(directory, true);
		assertEquals(expectedCounts(), actual.counts());
		assertTrue(hasSparsePath(actual.paths()),
				() -> "Expected automatic sparse execution, observed " + actual.paths()
						+ "; costs=" + actual.costs() + "; features=" + actual.features()
						+ "; decisions=" + actual.decisions());
	}

	@Test
	void choosesProjectedPredicateIncidenceAutomatically(@TempDir Path directory) {
		String query = """
				SELECT ?a ?b (COUNT(*) AS ?count) WHERE {
				  { SELECT DISTINCT ?s ?a WHERE { GRAPH ?g1 { ?s ?a ?o1 } } }
				  { SELECT DISTINCT ?s ?b WHERE { GRAPH ?g2 { ?s ?b ?o2 } } }
				  FILTER(STR(?a) < STR(?b))
				} GROUP BY ?a ?b
				""";
		LmdbStore store = new LmdbStore(directory.toFile(), new LmdbStoreConfig("spoc,psoc,posc,ospc")
				.setNativeEvaluationEnabled(true)
				.setDirectAdjacencyEnabled(true)
				.setDirectAdjacencyMode(DirectAdjacencyMode.PREFER)
				.setDirectAdjacencyCoverage(DirectAdjacencyCoverage.FULL));
		SailRepository repository = new SailRepository(store);
		try {
			repository.init();
			try (var connection = repository.getConnection()) {
				var vf = connection.getValueFactory();
				var graph1 = vf.createIRI(EX, "graph1");
				var graph2 = vf.createIRI(EX, "graph2");
				connection.begin();
				for (int subject = 0; subject < JOIN_KEYS; subject++) {
					for (int predicate = 0; predicate < ENDPOINTS; predicate++) {
						var s = vf.createIRI(EX, "subject" + subject);
						var p = vf.createIRI(EX, "predicate" + predicate);
						connection.add(s, p, vf.createIRI(EX, "object1"), graph1, graph2);
						connection.add(s, p, vf.createIRI(EX, "object2"), graph1, graph2);
					}
				}
				connection.commit();
			}
			assertTrue(AdjacencyEngagementTestAccess.buildNow(store));
			try (var connection = repository.getConnection()) {
				Set<String> paths = new LinkedHashSet<>();
				Set<String> quotes = new LinkedHashSet<>();
				GenericPlanNode plan = prepare(connection, query).explain(Explanation.Level.Telemetry)
						.toGenericPlanNode();
				collectPaths(plan, paths);
				collectMetric(plan, "nativeAggregateCostQuotesEstimated", quotes);
				int groups = 0;
				try (var results = prepare(connection, query).evaluate()) {
					while (results.hasNext()) {
						var result = results.next();
						assertEquals(JOIN_KEYS, ((Literal) result.getValue("count")).longValue());
						assertTrue(
								result.getValue("a").stringValue().compareTo(result.getValue("b").stringValue()) < 0);
						groups++;
					}
				}
				assertEquals(ENDPOINTS * (ENDPOINTS - 1) / 2, groups);
				assertTrue(hasSparsePath(paths),
						() -> "Expected automatic projected sparse execution, observed " + paths);
				assertTrue(quotes.stream()
						.anyMatch(value -> value.contains(
								"\"strategy\":\"sparseJoinAggregate\",\"physicalFeaturesKnown\":true")),
						() -> "Expected a complete physical quote for the executed sparse recipe: " + quotes);
				String sparseQuote = quotes.stream()
						.filter(value -> value.contains(
								"\"strategy\":\"sparseJoinAggregate\",\"physicalFeaturesKnown\":true"))
						.findFirst()
						.orElseThrow();
				Matcher probe = Pattern.compile("\\\"HASH_PROBE\\\":\\{[^}]*\\\"high\\\":([^}]+)\\}")
						.matcher(sparseQuote);
				assertTrue(probe.find(), sparseQuote);
				assertTrue(Double.parseDouble(probe.group(1)) >= 2D * JOIN_KEYS * ENDPOINTS * ENDPOINTS * ENDPOINTS,
						() -> "Hash probe bound must cover collisions: " + sparseQuote);
				assertTrue(sparseQuote.matches("(?s).*\\\"OUTPUT_MATERIALIZATION\\\":\\{[^}]*\\\"high\\\":null\\}.*"),
						() -> "Replay bytes remain unbounded without a term-width proof: " + sparseQuote);
			}
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void projectedIrCandidateQuotesItsGroupedProduct(@TempDir Path directory) {
		Observation actual = executeFixture(directory, true);
		assertEquals(expectedCounts(), actual.counts());
		assertIrGroupWork(actual);
	}

	@Test
	void marginalIrCandidateQuotesItsDistinctGroupedProduct(@TempDir Path directory) {
		Observation actual = executeFixture(directory, true, QUERY.replace("COUNT(?j)", "COUNT(DISTINCT ?j)"));
		assertEquals(expectedCounts(), actual.counts());
		assertIrGroupWork(actual);
	}

	private static void assertIrGroupWork(Observation actual) {
		String expected = "GROUP_UPDATE:" + ENDPOINTS * ENDPOINTS * JOIN_KEYS;
		String ir = actual.features()
				.stream()
				.flatMap(features -> Arrays.stream(features.split(",")))
				.filter(features -> features.startsWith("irAggregate="))
				.findFirst()
				.orElseThrow(() -> new AssertionError("IR candidate not admitted: " + actual.features()));
		assertTrue(Arrays.asList(ir.substring(ir.indexOf('=') + 1).split("\\|")).contains(expected),
				() -> "Expected " + expected + " in the IR quote: " + ir);
	}

	@Test
	void explicitDisableRetainsExactAutomaticResults(@TempDir Path directory) {
		System.setProperty(SPARSE_PROPERTY, "false");
		Observation actual = executeFixture(directory, true);
		assertEquals(expectedCounts(), actual.counts());
		assertFalse(hasSparsePath(actual.paths()), () -> "Disabled sparse route executed: " + actual.paths());
	}

	@Test
	void unavailableAdjacencyFallsBackWithoutChangingResults(@TempDir Path directory) {
		Observation actual = executeFixture(directory, false);
		assertEquals(expectedCounts(), actual.counts());
		assertFalse(hasSparsePath(actual.paths()), () -> "Sparse route requires adjacency: " + actual.paths());
	}

	private static Observation executeFixture(Path directory, boolean adjacency) {
		return executeFixture(directory, adjacency, QUERY);
	}

	private static Observation executeFixture(Path directory, boolean adjacency, String queryText) {
		LmdbStore store = new LmdbStore(directory.toFile(), new LmdbStoreConfig("spoc,psoc,posc,ospc")
				.setNativeEvaluationEnabled(true)
				.setDirectAdjacencyEnabled(adjacency)
				.setDirectAdjacencyMode(DirectAdjacencyMode.PREFER)
				.setDirectAdjacencyCoverage(DirectAdjacencyCoverage.FULL));
		SailRepository repository = new SailRepository(store);
		try {
			repository.init();
			try (var connection = repository.getConnection()) {
				var vf = connection.getValueFactory();
				var p = vf.createIRI(EX, "p");
				var q = vf.createIRI(EX, "q");
				connection.begin();
				for (int key = 0; key < JOIN_KEYS; key++) {
					var join = vf.createIRI(EX, "j" + key);
					for (int endpoint = 0; endpoint < ENDPOINTS; endpoint++) {
						connection.add(vf.createIRI(EX, "a" + endpoint), p, join);
						connection.add(join, q, vf.createIRI(EX, "b" + endpoint));
					}
				}
				connection.commit();
			}
			if (adjacency) {
				assertTrue(AdjacencyEngagementTestAccess.buildNow(store));
			}
			try (var connection = repository.getConnection()) {
				// Explain the first execution on a fresh store, before any query can train adaptive history.
				Set<String> paths = new LinkedHashSet<>();
				GenericPlanNode plan = prepare(connection, queryText).explain(Explanation.Level.Telemetry)
						.toGenericPlanNode();
				collectPaths(plan, paths);
				Set<String> costs = new LinkedHashSet<>();
				Set<String> features = new LinkedHashSet<>();
				Set<String> decisions = new LinkedHashSet<>();
				collectMetric(plan, "nativeStrategyProposalCosts", costs);
				collectMetric(plan, "nativeStrategyProposalFeatures", features);
				collectMetric(plan, "nativeDecision.GROUP.0", decisions);
				Map<Pair, Long> counts = new HashMap<>();
				try (var result = prepare(connection, queryText).evaluate()) {
					while (result.hasNext()) {
						var row = result.next();
						Pair pair = new Pair(row.getValue("a").stringValue(), row.getValue("b").stringValue());
						assertNull(counts.put(pair, ((Literal) row.getValue("count")).longValue()),
								"Duplicate group " + pair);
					}
				}
				return new Observation(counts, paths, costs, features, decisions);
			}
		} finally {
			repository.shutDown();
		}
	}

	private static SailTupleQuery prepare(SailRepositoryConnection connection, String queryText) {
		SailTupleQuery query = (SailTupleQuery) connection.prepareTupleQuery(queryText);
		query.setLmdbResultCacheRequested(false);
		return query;
	}

	private static Map<Pair, Long> expectedCounts() {
		Map<Pair, Long> expected = new HashMap<>();
		for (int left = 0; left < ENDPOINTS; left++) {
			for (int right = 0; right < ENDPOINTS; right++) {
				expected.put(new Pair(EX + "a" + left, EX + "b" + right), (long) JOIN_KEYS);
			}
		}
		return expected;
	}

	private static boolean hasSparsePath(Set<String> paths) {
		return paths.stream().anyMatch(path -> path.equals(SPARSE_PATH) || path.startsWith(SPARSE_PATH + "("));
	}

	private static void collectPaths(GenericPlanNode node, Set<String> paths) {
		String path = node.getStringMetricActual("nativeExecutionPath");
		if (path != null) {
			paths.add(path);
		}
		if (node.getPlans() != null) {
			for (GenericPlanNode child : node.getPlans()) {
				collectPaths(child, paths);
			}
		}
	}

	private static void collectMetric(GenericPlanNode node, String name, Set<String> values) {
		String value = node.getStringMetricActual(name);
		if (value != null) {
			values.add(value);
		}
		if (node.getPlans() != null) {
			for (GenericPlanNode child : node.getPlans()) {
				collectMetric(child, name, values);
			}
		}
	}

	private record Pair(String left, String right) {
	}

	private record Observation(Map<Pair, Long> counts, Set<String> paths, Set<String> costs, Set<String> features,
			Set<String> decisions) {
	}
}
